function setMaster(on,login){const input=$('#upload'),label=input?.closest('.upload'),btn=$('#masterModeBtn'),badge=$('#masterBadge');if(input)input.disabled=!on;if(label)label.classList.toggle('locked',!on);setControlLock(on);if(btn){btn.classList.toggle('on',on);btn.textContent=on?'마스터 모드 종료':'마스터 모드'}if(badge){badge.classList.toggle('on',on);badge.textContent=on?`마스터 활성 · ${login||''}`:'일반 조회 모드'}window.dispatchEvent(new CustomEvent('sf-master-mode-change',{detail:{on,login:login||''}}))}
